krpano.action:
set(isdisabled, false);
if(scene[%1] !== null,
  if(get(scene[%1].disabled) == true, set(isdisabled, true); );
);

set(layer[custom_block_msg].html, '이 씬은 현재 비활성화되어 있습니다.


' + %1);
set(layer[custom_block_msg].visible, true);
tween(layer[custom_block_msg].alpha, 1.0, 0.2);
delayedcall(custom_hide_block_msg, 2.0, tween(layer[custom_block_msg].alpha,0,0.4,default,set(layer[custom_block_msg].visible,false)); );

events.onnewscene:
if(scene[get(xml.scene)] !== null,
  if(get(scene[get(xml.scene)].disabled) == true,
    custom_show_block_msg(get(xml.scene));
    if(scene[home] !== null,
      loadscene(home, null, get(skin_settings.loadscene_flags), get(skin_settings.loadscene_blend));
    );
  );
);

events.onxmlcomplete:
if(action[skin_addthumbs] !== null,
  copy(action[skin_addthumbs__orig].content, action[skin_addthumbs].content);
  set(action[skin_addthumbs].content, get(action[custom_skin_addthumbs].content));
);
if(action[skin_loadscene] !== null,
  copy(action[skin_loadscene__orig].content, action[skin_loadscene].content);
  set(action[skin_loadscene].content, get(action[custom_skin_loadscene].content));
);
if(action[skin_nextscene] !== null,
  copy(action[skin_nextscene__orig].content, action[skin_nextscene].content);
  set(action[skin_nextscene].content, get(action[custom_skin_nextscene].content));
);
if(action[skin_nextscene_loop] !== null,
  copy(action[skin_nextscene_loop__orig].content, action[skin_nextscene_loop].content);
  set(action[skin_nextscene_loop].content, get(action[custom_skin_nextscene_loop].content));
);

krpano.action:

def(global.thumbarray, array);
set(thumbcount, 0);
for(set(i,0), i LT scene.count, inc(i),
  if(isvalue(scene[get(i)].thumburl) AND scene[get(i)].skipthumb != true AND scene[get(i)].disabled != true,

    set(thumbarray[get(thumbcount)], get(scene[get(i)]));
    set(scene[get(i)].sceneindex, get(i));
    set(scene[get(i)].thumbindex, get(thumbcount));
    inc(thumbcount);
  );
);

if(skin_settings.thumbs == false,
  set(layer[skin_btn_thumbs].visible,false);
  ,
  copy(thumbwidth, skin_settings.thumbs_width);
  copy(thumbheight, skin_settings.thumbs_height);
  copy(thumbpadding, skin_settings.thumbs_padding);
  copy(thumbcrop, skin_settings.thumbs_crop);

  calc(thumbxoffset, thumbwidth + thumbpadding);
  calc(thumbxcenter, thumbxoffset * 0.5);
  calc(thumbbarwidth, thumbxoffset * thumbcount + thumbpadding);
  calc(thumbbarheight, thumbpadding + thumbheight + thumbpadding);

  if(skin_settings.thumbs_scrollindicator,
    copy(layer[skin_thumbs_scrollindicator].y, thumbbarheight);
    add(thumbbarheight, layer[skin_thumbs_scrollindicator].height);
  );

  set(layer[skin_thumbs], width=get(thumbbarwidth), height=get(thumbbarheight) );

  calc(layer[skin_thumbs_scrollleft].y, thumbbarheight * 0.5);
  calc(layer[skin_thumbs_scrollright].y, thumbbarheight * 0.5);


  set(layer[skin_thumbborder], parent=null, visible=false);
  calc(ii,layer.count-1);
  loop(ii GE 0,
    if (indexof(layer[get(ii)].name, 'skin_thumb_') == 0 OR indexof(layer[get(ii)].name, 'skin_thumbtext_') == 0,
      removelayer(get(ii),true);
    );
    dec(ii),
  );

  for(set(i,0), i LT thumbcount, inc(i),

    copy(currentscene, thumbarray[get(i)]);

    calc(thumbname, 'skin_thumb_' + i);
    addlayer(get(thumbname));

    set(layer[get(thumbname)],
      url=get(currentscene.thumburl),
      keep=true,
      parent='skin_thumbs',
      align='lefttop',
      crop=get(thumbcrop),
      width=get(thumbwidth),
      height=get(thumbheight),
      x=calc(thumbpadding + i*thumbxoffset),
      y=get(thumbpadding),
      linkedscene=get(currentscene.name),
      onclick='copy(layer[skin_thumbborder].parent, name); skin_loadscene(get(linkedscene),get(skin_settings.loadscene_blend));'
    );

    set(currentscene,
      thumbx=calc(thumbpadding + i*thumbxoffset + thumbxcenter),
      thumby=get(thumbpadding)
    );

    if(skin_settings.tooltips_thumbs,
      set(layer[get(thumbname)].tooltip, get(currentscene.title) );
      layer[get(thumbname)].loadstyle(skin_tooltips);
    );

    if(skin_settings.thumbs_text,
      calc(thumbtext, 'skin_thumbtext_' + i);
      addlayer(get(thumbtext));
      layer[get(thumbtext)].loadstyle(skin_thumbtext_style);
      set(layer[get(thumbtext)], keep=true, parent=get(thumbname), html=get(currentscene.title) );
    );
  );

  if(thumbcount == 1,
    set(layer[skin_thumbs].align, 'lefttop');
    ,
    set(layer[skin_thumbs].align, 'top');
  );
);


set(targetscene, null);

if(scene[get(newscenenameorindex)] !== null,

  copy(targetscene, newscenenameorindex);
  ,
  if(scene[get(newscenenameorindex)].name !== null,

    copy(targetscene, scene[get(newscenenameorindex)].name);
    ,

    if(newscenenameorindex GE 0 AND newscenenameorindex LT scene.count,
      copy(targetscene, scene[get(newscenenameorindex)].name);
    );
  );
);

if(targetscene == null,
  custom_show_block_msg('Scene not found: ' + newscenenameorindex);
  ,

  if(scene[get(targetscene)].disabled == true,
    custom_show_block_msg(get(targetscene));
    ,

    if(webvr.isenabled AND scene.count GT 1,
      set(hotspot[skin_webvr_prev_scene].visible, false);
      set(hotspot[skin_webvr_next_scene].visible, false);
    );

    calc(parentname, 'skin_thumb_' + scene[get(targetscene)].thumbindex);
    if(scene[get(targetscene)].thumburl AND scene[get(targetscene)].skipthumb != true AND layer[get(parentname)],
      set(layer[skin_thumbborder], parent=get(parentname), visible=true);
      ,
      set(layer[skin_thumbborder].visible, false);
    );

    layer[skin_thumbs].scrolltocenter(get(scene[get(targetscene)].thumbx), get(scene[get(targetscene)].thumby));

    if(blendmode == null,
      blendmode = skin_settings.loadscene_blend;
    );

    loadscene(get(targetscene), null, get(skin_settings.loadscene_flags), get(blendmode));
  );
);

set(newscenename, null);

if(isset(scene[get(xml.scene)].thumbindex),

  set(tries, 0);
  add(newsceneindex, scene[get(xml.scene)].thumbindex, indexadd);

  while(tries LT thumbarray.length AND newscenename == null,
    if(newsceneindex GE 0 AND newsceneindex LT thumbarray.length,
      set(candidate, get(thumbarray[get(newsceneindex)].name));
      if(scene[get(candidate)].disabled != true,
        set(newscenename, get(candidate));
      );
    );
    add(newsceneindex, indexadd);
    inc(tries);
  );

  ,
  set(tries, 0);
  add(newsceneindex, scene[get(xml.scene)].index, indexadd);

  while(tries LT scene.count AND newscenename == null,
    if(newsceneindex GE 0 AND newsceneindex LT scene.count,
      set(candidate, get(scene[get(newsceneindex)].name));
      if(scene[get(candidate)].disabled != true,
        set(newscenename, get(candidate));
      );
    );
    add(newsceneindex, indexadd);
    inc(tries);
  );
);

if(newscenename != null,
  skin_loadscene(get(newscenename), calc(indexadd LT 0 ? skin_settings.loadscene_blend_prev : skin_settings.loadscene_blend_next));
);

set(newscenename, null);

if(isset(scene[get(xml.scene)].thumbindex),

  sub(lastsceneindex, thumbarray.length, 1);
  add(newsceneindex, scene[get(xml.scene)].thumbindex, indexadd);

  set(tries, 0);
  while(tries LT thumbarray.length AND newscenename == null,

    if(newsceneindex LT 0, copy(newsceneindex,lastsceneindex));
    if(newsceneindex GT lastsceneindex, set(newsceneindex,0));

    set(candidate, get(thumbarray[get(newsceneindex)].name));
    if(scene[get(candidate)].disabled != true,
      set(newscenename, get(candidate));
    );

    add(newsceneindex, indexadd);
    inc(tries);
  );

  ,
  sub(lastsceneindex, scene.count, 1);
  add(newsceneindex, scene[get(xml.scene)].index, indexadd);

  set(tries, 0);
  while(tries LT scene.count AND newscenename == null,

    if(newsceneindex LT 0, copy(newsceneindex,lastsceneindex));
    if(newsceneindex GT lastsceneindex, set(newsceneindex,0));

    set(candidate, get(scene[get(newsceneindex)].name));
    if(scene[get(candidate)].disabled != true,
      set(newscenename, get(candidate));
    );

    add(newsceneindex, indexadd);
    inc(tries);
  );
);

if(newscenename != null,
  skin_loadscene(get(newscenename), calc(indexadd LT 0 ? skin_settings.loadscene_blend_prev : skin_settings.loadscene_blend_next));
);
